from pathlib import Path
import pandas as pd

# ============================================================
# CONFIGURATION
# ============================================================

HERE = Path(__file__).parent
files = sorted(HERE.glob("openpowerlifting-*.csv"))

if not files:
    raise FileNotFoundError(
        "No openpowerlifting-*.csv file found in this folder."
    )

csv_path = files[-1]

# All charts generated by this script use Australian competitions
# held in 2026.
START_DATE = pd.Timestamp("2026-01-01")
END_DATE = pd.Timestamp("2026-12-31")

age_distribution_path = HERE / "chart3_age_distribution.csv"
age_dots_path = HERE / "chart3_age_vs_dots.csv"

print(f"Reading {csv_path.name}...")

# ============================================================
# LOAD DATA
# ============================================================

df = pd.read_csv(
    csv_path,
    usecols=[
        "Name",
        "Date",
        "MeetCountry",
        "Sex",
        "Age",
        "Event",
        "Equipment",
        "BodyweightKg",
        "Best3SquatKg",
        "Best3BenchKg",
        "Best3DeadliftKg",
        "TotalKg",
        "Dots",
    ],
    low_memory=False,
)

df["Date"] = pd.to_datetime(df["Date"], errors="coerce")

# Convert numeric fields safely.
numeric_columns = [
    "Age",
    "BodyweightKg",
    "Best3SquatKg",
    "Best3BenchKg",
    "Best3DeadliftKg",
    "TotalKg",
    "Dots",
]

for column in numeric_columns:
    df[column] = pd.to_numeric(df[column], errors="coerce")

# ============================================================
# FILTER ONCE: AUSTRALIA + 2026 + VALID RAW FULL-POWER RESULTS
# ============================================================

country_is_australia = (
    df["MeetCountry"]
    .astype("string")
    .str.strip()
    .str.casefold()
    .eq("australia")
)

is_raw = (
    df["Equipment"]
    .astype("string")
    .str.strip()
    .str.casefold()
    .eq("raw")
)

is_full_power = (
    df["Event"]
    .astype("string")
    .str.strip()
    .eq("SBD")
)

valid_results = (
    df["Name"].notna()
    & df["Sex"].isin(["M", "F"])
    & df["Age"].between(14, 100)
    & df["BodyweightKg"].gt(0)
    & df["Best3SquatKg"].gt(0)
    & df["Best3BenchKg"].gt(0)
    & df["Best3DeadliftKg"].gt(0)
    & df["TotalKg"].gt(0)
    & df["Dots"].notna()
)

df = df[
    country_is_australia
    & df["Date"].between(START_DATE, END_DATE)
    & is_raw
    & is_full_power
    & valid_results
].copy()

if df.empty:
    raise ValueError(
        "No valid Australian raw full-power results found for 2026. "
        "Check the dataset's Equipment and Event values."
    )

print(f"\nFiltered competition results: {len(df):,}")
print(f"Date range: {START_DATE.date()} to {END_DATE.date()}")
print("Competition country: Australia")
print("Event: SBD (squat, bench press and deadlift)")
print("Equipment: Raw")

# ============================================================
# SELECT ONE BEST RESULT PER LIFTER
# ============================================================

# Use the highest DOTS result from their eligible 2026 competitions.
# Names are not guaranteed to uniquely identify real people.
best_lifters = (
    df.sort_values("Dots", ascending=False)
    .drop_duplicates(subset=["Name", "Sex"])
    .copy()
)

print(f"Unique name/sex combinations: {len(best_lifters):,}")


# AGE DISTRIBUTION BY SEX

age_bins = [14, 25, 35, 45, 55, 65, 101]
age_labels = [
    "14-24",
    "25-34",
    "35-44",
    "45-54",
    "55-64",
    "65+",
]

best_lifters["age_group"] = pd.cut(
    best_lifters["Age"],
    bins=age_bins,
    labels=age_labels,
    right=False,
)

age_distribution = (
    best_lifters.dropna(subset=["age_group"])
    .groupby(["Sex", "age_group"], observed=False)
    .size()
    .reset_index(name="lifters")
)

age_distribution.to_csv(age_distribution_path, index=False)

print("\nAge distribution by sex:")
print(age_distribution.to_string(index=False))
print(f"Saved: {age_distribution_path}")


# Age vs DOTS scatter plot: randomly sample 100 lifters per sex
age_dots = best_lifters[
    ["Name", "Sex", "Age", "Dots", "BodyweightKg",
     "Best3SquatKg", "Best3BenchKg", "Best3DeadliftKg",
     "TotalKg", "Date"]
].copy()

# Sample up to 100 lifters from each sex
age_dots = (
    age_dots.groupby("Sex", group_keys=False)
    .sample(n=100, random_state=42, replace=False)
)

age_dots = age_dots.rename(columns={
    "Dots": "DOTS",
    "BodyweightKg": "bodyweight_kg",
    "Best3SquatKg": "squat_kg",
    "Best3BenchKg": "bench_kg",
    "Best3DeadliftKg": "deadlift_kg",
    "TotalKg": "total_kg"
})

age_dots["Date"] = age_dots["Date"].dt.strftime("%Y-%m-%d")
age_dots.to_csv(age_dots_path, index=False)


print("\nSample of age versus DOTS data:")
print(age_dots.head(10).to_string(index=False))
print(f"Saved: {age_dots_path}")

print("\nAll CSV exports finished.")

# Bodyweight vs total lifted
bodyweight_total_path = HERE / "chart4_bodyweight_vs_total.csv"

bodyweight_total = best_lifters[
    [
        "Name",
        "Sex",
        "Age",
        "BodyweightKg",
        "TotalKg",
        "Dots",
        "Date",
    ]
].copy()

bodyweight_total = bodyweight_total.rename(columns={
    "BodyweightKg": "bodyweight_kg",
    "TotalKg": "total_kg",
    "Dots": "DOTS",
})

bodyweight_total["Date"] = (
    bodyweight_total["Date"].dt.strftime("%Y-%m-%d")
)

bodyweight_total.to_csv(bodyweight_total_path, index=False)

print(f"Saved {len(bodyweight_total)} rows to {bodyweight_total_path}")


# Lift composition of the top 10
lift_composition_path = HERE / "chart4_top10_lift_composition.csv"

# Select the top 5 women and top 5 men by DOTS.
top_women = (
    best_lifters[best_lifters["Sex"] == "F"]
    .nlargest(5, "Dots")
    .copy()
)

top_men = (
    best_lifters[best_lifters["Sex"] == "M"]
    .nlargest(5, "Dots")
    .copy()
)

# Assign labels that distinguish women from men.
top_women["Person"] = [
    f"Woman {i}" for i in range(1, len(top_women) + 1)
]

top_men["Person"] = [
    f"Man {i}" for i in range(1, len(top_men) + 1)
]

top10 = pd.concat([top_women, top_men], ignore_index=True)

# Keep one row per person, with the three lift values.
lift_composition = top10[
    [
        "Person",
        "Name",
        "Sex",
        "Best3SquatKg",
        "Best3BenchKg",
        "Best3DeadliftKg",
        "TotalKg",
        "Dots",
    ]
].rename(columns={
    "Best3SquatKg": "squat_kg",
    "Best3BenchKg": "bench_kg",
    "Best3DeadliftKg": "deadlift_kg",
    "TotalKg": "total_kg",
    "Dots": "DOTS",
})

lift_composition.to_csv(lift_composition_path, index=False)

print("\nTop 10 lifters by DOTS:")
print(
    lift_composition[
        ["Person", "Name", "Sex", "squat_kg", "bench_kg",
         "deadlift_kg", "total_kg", "DOTS"]
    ].to_string(index=False)
)

print(f"\nSaved {len(lift_composition)} rows to {lift_composition_path}")